            toStringOutput.Add($"ServiceNameExpression = {this.ServiceNameExpression ?? "null"}");
            toStringOutput.Add($"ServiceVersionExpression = {this.ServiceVersionExpression ?? "null"}");
            toStringOutput.Add($"ResourceAttributesExpression = {this.ResourceAttributesExpression ?? "null"}");
            toStringOutput.Add($"EventAttributesExpression = {this.EventAttributesExpression ?? "null"}");
